import '../../../../../../Core/Storage/Remote/api_service.dart';import '../../../../../../Core/Models/all_categories.dart';import '../../../../../../Core/Models/product_model.dart';import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../entities/all_categories_entities.dart';import '../entities/category_data_entities.dart';class ExploreData {  static Future<List<AllCategoriesEntities>> getAllCategories() async {    final response = await DioHelper.getData(      path: ApiEndpoints.allCategory,    );    return (response?.data["data"] as List)        .map(          (item) => AllCategoriesEntities.fromCategories(            AllCategories.fromJson(item),          ),        )        .toList();  }  static Future<List<CategoryDataPreviewEntities>> getProductsCategory(      {required int id}) async {    final response = await DioHelper.getData(      path:          "${ApiEndpoints.getProductsByCategories}$id${(ApiEndpoints.product)}",    );    return (response?.data["data"]["products"] as List)        .map(          (item) => CategoryDataPreviewEntities.fromProduct(            ProductModel.fromJson(item),          ),        )        .toList();  }}